#[using="Type"] Lemma rmrep_put_meta_frame : forall st m m' g mr',
  rmrep st m -> meta_slot st g ->
  munch [(conc st g, conc st g + META_SIZE)] m m' -> wmono rsegs m m' ->
  rw_cells rsegs m' (conc st g) (meta_cells st mr') ->
  rmrep (put_meta g mr' st) m'.
Proof.
intros st m m' g mr' MR (a & ar & k & Ha & Hk & Eg) MU WM CH. pose proof MR as (WF & CX & GL & AR & GR & SH). destruct (rarea_conc st a ar WF Ha) as (ra & Hra & Ca & Sa0 & Sa1 & SaL & NK & RB0 & RBAL & RBC). pose_ceil. assert (HG : conc st g = conc st a + (AREA_HDR + META_SIZE * k)) by (rewrite Eg, conc_aadd by (rewrite Hra; eauto); reflexivity). unfold AREA_HDR, META_SIZE, NSLOTS in *. pose proof WF as (Hres & WR & DJ & WA & WG). destruct (WR (fst a) ra Hra) as (_ & _ & _ & _ & RFa). destruct (rreserved_disjoint _ _ RFa) as [_ DRa]. pose proof (round_up_pg_ge (r_len ra)) as RU. assert (Hconc : forall q, conc (put_meta g mr' st) q = conc st q) by (intros; reflexivity). assert (Hpw : forall q, pw (put_meta g mr' st) q = pw st q) by (intros [q|]; reflexivity). assert (Hmc : forall mr, meta_cells (put_meta g mr' st) mr = meta_cells st mr) by (intros; unfold meta_cells; rewrite !Hpw; reflexivity). assert (TC : forall A cs, rw_cells rsegs m A cs -> (A + Z.of_nat (cells_size cs) <= conc st g \/ conc st g + 40 <= A) -> rw_cells rsegs m' A cs). { intros A cs H HD. eapply rw_cells_transport; eauto. cbn. split; [lia|exact I]. } split; [|split; [|split; [|split; [|split]]]]. - exact WF. - eapply rmrep_ctx_ext; [reflexivity|exact Hconc|]. destruct CX as (C1 & C2 & C3 & C4 & C5 & C6). unfold rmrep_ctx. unfold RCTX in *. assert (L1 : length (actives st) = 48%nat) by (unfold actives; rewrite map_length, seq_length; reflexivity). assert (L2 : length (usages st) = 48%nat) by (unfold usages; rewrite map_length, seq_length; reflexivity). assert (L3 : length (unmap_seqs st) = 32%nat) by (unfold unmap_seqs; rewrite map_length, seq_length; reflexivity). assert (L4 : length (bouncess st) = 32%nat) by (unfold bouncess; rewrite map_length, seq_length; reflexivity). split; [|split; [|split; [|split; [|split]]]]. + apply TC; [exact C1 | cbn; lia]. + eapply u64arr_transport; eauto. cbn [disjoint_from]. rewrite L1. split; [lia|exact I]. + eapply u64arr_transport; eauto. cbn [disjoint_from]. rewrite L2. split; [lia|exact I]. + eapply u8arr_transport; eauto. cbn [disjoint_from]. rewrite L3. split; [lia|exact I]. + eapply u8arr_transport; eauto. cbn [disjoint_from]. rewrite L4. split; [lia|exact I]. + apply TC; [exact C6 | cbn; lia]. - destruct GL as (G1 & G2 & G3 & G4 & G5 & G6). unfold rmrep_globals, RMLOCK, RNEED_LOCKS, RPAGE_SIZE, RGOT_SSP, RSSP_GUARD in *. split; [|split; [|split; [|split; [|split]]]]; (apply TC; [assumption | cbn; lia]). - intros a' ar' Ha'. cbn in Ha'. destruct (rarea_conc st a' ar' WF Ha') as (ra' & Hra' & Ca' & Sa0' & Sa1' & SaL' & NK' & _). destruct (decide (a' = a)) as [->|NEa]. + rewrite Ha in Ha'. inversion Ha'; subst ar'. destruct (AR a ar Ha) as (HD & SL & PD). unfold rarea_rep. rewrite !Hconc, Hpw. split; [|split]. * apply TC; [exact HD| cbn; lia]. * intros k' Hk'. rewrite Hmc, get_meta_rec_put. destruct (Z.eq_dec k' k) as [->|NEk]. -- rewrite <- Eg, aptr_eqb_refl. replace (conc st a + 24 + 40 * k) with (conc st g) by (rewrite HG; lia). exact CH. -- replace (aptr_eqb (aadd a (24 + 40 * k')) g) with false. 2:{ symmetry. rewrite Eg. unfold aptr_eqb, aadd. cbn. rewrite N.eqb_refl. cbn. apply Z.eqb_neq. lia. } apply TC; [apply SL; lia|]. unfold meta_cells. cbn [cells_size csize Nat.add length]. unfold AREA_HDR, META_SIZE. nia. * apply TC; [exact PD| cbn; lia]. + assert (PG : fst a' <> fst a \/ (fst a' = fst a /\ (snd a' + 4096 <= snd a \/ snd a + 4096 <= snd a'))). { destruct (N.eq_dec (fst a') (fst a)) as [E|NE]; [right|left; exact NE]. split; [exact E|]. assert (snd a' <> snd a) by (intros E2; apply NEa; destruct a, a'; cbn in *; congruence). Z.div_mod_to_equations. nia. } assert (DD : conc st a' + 4096 <= conc st g \/ conc st g + 40 <= conc st a'). { rewrite Ca', HG, Ca. destruct PG as [NE|[E PG]]. - pose proof (rarea_lr_lo st a ar ra WF Ha Hra). pose proof (rarea_lr_lo st a' ar' ra' WF Ha' Hra'). destruct (DJ (fst a') ra' (fst a) ra Hra' Hra NE); lia. - rewrite E, Hra in Hra'. inversion Hra'; subst ra'. lia. } eapply rarea_rep_ext; [exact Hconc| |]. { intros k0 Hk0. rewrite get_meta_rec_put. unfold AREA_HDR, META_SIZE, NSLOTS in *. replace (aptr_eqb (aadd a' (24 + 40 * k0)) g) with false; [reflexivity|]. symmetry. rewrite Eg. unfold aptr_eqb, aadd. cbn [fst snd]. destruct PG as [NE|[E PG]]. - rewrite (proj2 (N.eqb_neq _ _) NE). reflexivity. - rewrite E, N.eqb_refl. cbn [andb]. apply Z.eqb_neq. lia. } destruct (AR a' ar' Ha') as (HD & SL & PD). split; [|split]. * apply TC; [exact HD| cbn; lia]. * intros k0 Hk0. apply TC; [apply SL; exact Hk0|]. unfold meta_cells. cbn [cells_size csize Nat.add length]. unfold AREA_HDR, META_SIZE, NSLOTS in *. nia. * apply TC; [exact PD| cbn; lia]. - intros b gh Hb. cbn in Hb. eapply rgroup_rep_ext; [exact Hconc|]. destruct (rgroup_conc st b gh WF Hb) as (rb & Hrb & Cb & Kb & Sb0 & Sb1 & _). destruct (GR b gh Hb) as (w8 & R & Hw8). exists w8. split; [|exact Hw8]. apply TC; [exact R|]. cbn. rewrite Cb, HG, Ca. assert (NE : fst b <> fst a) by (intros E; rewrite E, Hra in Hrb; inversion Hrb; subst; congruence). pose proof (rarea_lr_lo st a ar ra WF Ha Hra). pose proof (lr_lo_group rb Kb). destruct (DJ (fst b) rb (fst a) ra Hrb Hra NE); lia. - intros rid r' Hr' Hk'. cbn in Hr'. eapply rshadow_rep_ext; [reflexivity|]. destruct (SH rid r' Hr' Hk') as [HWr HB]. split; [eapply wr_at_transport; eauto|]. intros o v Ho Hc. destruct (HB o v Ho Hc) as [Bt Hv]. split; [|exact Hv]. eapply bytes_at_transport; eauto. cbn. split; [|exact I]. assert (NE : rid <> fst a) by (intros E; subst; rewrite Hra in Hr'; inversion Hr'; subst; congruence). pose proof (rarea_lr_lo st a ar ra WF Ha Hra). pose proof (lr_lo_group r' Hk'). rewrite HG, Ca. destruct (DJ rid r' (fst a) ra Hr' Hra NE); lia. Qed.

