#[using="Type"] Lemma rmeta_slot_bounds : forall st m g, rmrep st m -> meta_slot st g ->
  0 < conc st g /\ conc st g + 40 <= alloc_ceiling /\ (conc st g + 40 <= 0x10000 \/ 0xfa000 <= conc st g) /\ conc st g mod 4 = 0
  /\ conc st g mod 4096 >= 24.
Proof.
