  let n := Z.shiftl 2 (c_meta_alloc_shift (ctx st)) in
  evt rsegs (fun ms' => ms' = MS (mkR (Z_to_bv 64 0xabe30) sp gp tp t0 t1 t2 (Z_to_bv 64 4096) (Z_to_bv 64 n)
