  0 < cur -> cur + 8192 < 2^64 ->
  rw_cells rsegs m (RCTX + 912) [C1 q0; CB 7 q1; C8 (Z_to_bv 64 cur)] ->
  evt rsegs (fun ms' => ms' = MS (mkR (Z_to_bv 64 0xabdd8) sp gp tp t0 t1 t2 (Z_to_bv 64 4096) (Z_to_bv 64 (cur + 8192))
